void jump_to_ns(uint32_t addr)
{
	//Don't display any log because all uart maybe disabled by caller!
	ns_reset_handler_t fn;
	__TZ_set_MSP_NS(*(( uint32_t *)(addr)));
	fn = (ns_reset_handler_t)(*(( uint32_t * ) (( addr ) + 4U )));
	fn();
}

void jump_to_s(uint32_t addr)
{
	uint32_t msp = 0;
	uint32_t pc  = 0;

	BK_LOGD(TAG, "Next Image Addr: 0x%x\n", addr);
	msp = *(uint32_t *)addr;
	pc  = *(uint32_t *)(addr + 4);

	BK_LOGD(TAG, "Set MSP: 0x%x\n", (unsigned int)msp);
	BK_LOGD(TAG, "Jump to S: 0x%x\n", (unsigned int)pc);

	__set_MSP(msp);
	__DSB();
	__ISB();

	/* relocate vecotr table */
	SCB->VTOR = (addr);
	__DSB();
	__ISB();

	/* save next entry to r9 */
	__asm__ volatile("mov r9, %0" : : "r"(pc) : "memory");

	/* clear all general registers */
	__asm__ volatile(
		"mov r0, #0;\n\t"
		"mov r1, r0;\n\t"
		"mov r2, r0;\n\t"
		"mov r3, r0;\n\t"
		"mov r4, r0;\n\t"
		"mov r5, r0;\n\t"
		"mov r6, r0;\n\t"
		"mov r7, r0;\n\t"
		"mov r8, r0;\n\t"
		"mov r10, r0;\n\t"
		"mov r11, r0;\n\t"
		"mov r12, r0;\n\t"
		"dsb;\n\t"
		"isb;\n\t"
		"bx r9;\n\t"
		"b .;\n\t"	  /* should not be here */
		);
}

	return addr;
}

void reset_cpu1_core(uint32 offset, uint32_t start_flag)
{
	BK_LOGD(NULL, "reset_cpu1_core at: %08x, start=%d\r\n", offset, start_flag);

	sys_drv_set_cpu1_pwr_dw(0);
	sys_drv_set_cpu1_rxevt_sel(1); // for cpu0 + smp(cpu1,cpu2)
	sys_drv_set_cpu1_boot_address_offset(offset >> 8);
	sys_drv_set_cpu1_reset(start_flag);

}

