   282	#ifdef CONFIG_ARM_SYSTICK_IRQ_WQUEUE
   283	static int systick_isr_handle(int irq, void *regs, void *arg)
   284	{
   285	  return IRQ_WAKE_THREAD;
   286	}
   287	#endif
   288	
   289	/****************************************************************************
   290	 * Public Functions
   291	 ****************************************************************************/
   292	
   293	struct timer_lowerhalf_s *systick_initialize(bool coreclk,
   294	                                             unsigned int freq, int minor)
   295	{
   296	  struct systick_lowerhalf_s *lower =
   297	    (struct systick_lowerhalf_s *)&g_systick_lower;
   298	
   299	  /* Calculate the working clock frequency if need */
   300	
   301	  if (freq == 0)
   302	    {
   303	      uint32_t calib = getreg32(NVIC_SYSTICK_CALIB);
   304	      uint32_t tenms = calib & NVIC_SYSTICK_CALIB_TENMS_MASK;
   305	      lower->freq = 100 * (tenms + 1);
   306	    }
   307	  else
   308	    {
   309	      lower->freq = freq;
   310	    }
   311	
   312	  /* Disable SYSTICK, but enable interrupt */
   313	
   314	  if (coreclk)
   315	    {
   316	      putreg32(NVIC_SYSTICK_CTRL_CLKSOURCE | NVIC_SYSTICK_CTRL_TICKINT,
   317	               NVIC_SYSTICK_CTRL);
   318	    }
   319	  else
   320	    {
   321	      putreg32(NVIC_SYSTICK_CTRL_TICKINT, NVIC_SYSTICK_CTRL);
   322	    }
   323	
   324	#ifdef CONFIG_ARM_SYSTICK_IRQ_WQUEUE
   325	  irq_attach_wqueue(NVIC_IRQ_SYSTICK, systick_isr_handle,
   326	                    systick_interrupt, lower,
   327	                    CONFIG_ARMV7M_SYSTICK_IRQ_WQUEUE_PRIORITY);
   328	#else
   329	  irq_attach(NVIC_IRQ_SYSTICK, systick_interrupt, lower);
   330	#endif
   331	  up_enable_irq(NVIC_IRQ_SYSTICK);
   332	
   333	  /* Register the timer driver if need */
   334	
   335	  if (minor >= 0)
   336	    {
   337	      char devname[32];
   338	
   339	      snprintf(devname, sizeof(devname), "/dev/timer%d", minor);
   340	      timer_register(devname, (struct timer_lowerhalf_s *)lower);
   341	    }
   342	
   343	  return (struct timer_lowerhalf_s *)lower;
   344	}
   345	
   346	#endif /* CONFIG_ARM_SYSTICK */
