const [uartOpen, initFlow, peer, termios] = await Promise.all([
  tools.bash({workdir:"/home/czp/openvela_contest/nuttx",description:"Reads console UART open lifecycle","command":"nl -ba drivers/serial/serial.c | sed -n '650,790p'; rg -n -C 5 -F -e 'arm_serialinit' -e 'up_serialinit' -e 'serialinit' sched arch/arm/src/arm_m arch/arm/src/armv8-m -g '*.[ch]' | sed -n '1,400p'"}),
  tools.bash({workdir:"/home/czp/openvela_contest/nuttx",description:"Finds console RX setup patterns","command":"rg -n -C 6 -F -e 'void arm_serialinit' -e 'void up_serialinit' arch/arm/src -g '*serial*.c' | sed -n '1,520p'; rg -n -C 5 -F -e 'isconsole' arch/arm/src -g '*serial*.c' | sed -n '1,420p'"}),
  tools.bash({workdir:"/home/czp/openvela_contest/contest2026_272_tokenwujixian/.worktrees/bk7258-devkit",description:"Reads BK7258 console initialization code","command":"nl -ba chips/bk7258/bk7258_uart.c | sed -n '1,230p'; nl -ba chips/bk7258/bk7258_lowputc.c | sed -n '1,100p'; nl -ba chips/bk7258/bk7258_gpio.c | sed -n '1,100p'; rg -n -C 4 -F -e 'arm_serialinit' -e 'bk7258_uart_setup' -e 'bk7258_gpio_uart0_rx' chips/bk7258 -g '*.[ch]'"}),
  tools.bash({workdir:"/home/czp/openvela_contest",description:"Checks host serial flow-control flags","command":"stty -F /dev/ttyUSB0 -a 2>&1 || true; fuser -v /dev/ttyUSB0 2>&1 || true"})
]);
return {uartOpen:uartOpen.output,initFlow:initFlow.output,peer:peer.output,termios:termios.output};

