   886	   * we add data to the head of the buffer; uart_xmitchars takes the
   887	   * data from the end of the buffer.
   888	   */
   889	
   890	  while ((size_t)recvd < buflen)
   891	    {
   892	#ifdef CONFIG_SERIAL_REMOVABLE
   893	      /* If the removable device is no longer connected, refuse to read any
   894	       * further from the device.
   895	       */
   896	
   897	      if (dev->disconnected)
