   204	void arm_serialinit(void)
   205	{
   206	  /* The serial core treats a console as pre-initialized and skips setup() on
   207	   * its first open. Complete RX pinmux and UART receive enable before
   208	   * registering the console so NSH can receive input as well as emit early
   209	   * polling output. */
   210	
   211	  (void)bk7258_uart_setup(&g_uartport);
