*** Begin Patch
*** Update File: /home/czp/openvela_contest/contest2026_272_tokenwujixian/.worktrees/bk7258-devkit/chips/bk7258/include/bk7258_memorymap.h
@@
-#define BK7258_UART_INT_RX_READY  (UINT32_C(1) << 1)
-#define BK7258_UART_INT_RX_FINISH (UINT32_C(1) << 6)
+#define BK7258_UART_INT_TX_READY  (UINT32_C(1) << 0)
+#define BK7258_UART_INT_RX_READY  (UINT32_C(1) << 1)
+#define BK7258_UART_INT_RX_FINISH (UINT32_C(1) << 6)
*** Update File: /home/czp/openvela_contest/contest2026_272_tokenwujixian/.worktrees/bk7258-devkit/chips/bk7258/bk7258_uart.c
@@
 static void bk7258_uart_txint(struct uart_dev_s *dev, bool enable)
 {
   struct bk7258_uart_s *priv = dev->priv;

   if (enable)
     {
+      /* Start the transfer immediately, then leave the hardware FIFO-ready
+       * interrupt enabled so that the ISR drains any bytes which did not fit
+       * in the FIFO on this first pass. */
+
+      priv->ie |= BK7258_UART_INT_TX_READY;
+      putreg32(priv->ie, BK7258_UART_INT_ENABLE);
       uart_xmitchars(dev);
     }
-
-  priv->ie &= ~UINT32_C(1);
-  putreg32(priv->ie, BK7258_UART_INT_ENABLE);
+  else
+    {
+      priv->ie &= ~BK7258_UART_INT_TX_READY;
+      putreg32(priv->ie, BK7258_UART_INT_ENABLE);
+    }
@@
   if (status & (BK7258_UART_INT_RX_READY | BK7258_UART_INT_RX_FINISH))
     {
       uart_recvchars(dev);
     }
+
+  if (status & BK7258_UART_INT_TX_READY)
+    {
+      uart_xmitchars(dev);
+    }

   return OK;
 }
*** Update File: /home/czp/openvela_contest/contest2026_272_tokenwujixian/.worktrees/bk7258-devkit/investigation/bk7258-hardfault/hypotheses.tsv
@@
 H05	Console RX setup is skipped because the NuttX serial core treats isconsole devices as pre-initialized	Initializing GPIO10 RX and UART RX_EN before registering /dev/console makes NSH accept typed characters	Call bk7258_uart_setup() from arm_serialinit(), rebuild, package, and test interactive NSH	pending	testing	serial.c skips uart_setup() for dev->isconsole on first open; current arm_earlyserialinit configures only TX through bk7258_lowsetup().
+H06	UART TX interrupt is disabled after the first FIFO fill and the ISR ignores TX-ready status	Keeping TX-ready enabled and draining it in the ISR sends complete NSH output without a second input event	Enable bit 0 while buffered TX remains and invoke uart_xmitchars() for TX-ready status, then rebuild, package, and test help output	pending	testing	Current txint() always clears bit 0 after its initial synchronous transmit, and UART ISR handles only RX bits 1 and 6.
*** End Patch

